# FieldBoundary: dataclass + validator
from dataclasses import dataclass, field
from typing import Any

@dataclass
class Fieldboundary:
    field_id: str = None  # Unique ID
    name: str = None  # Field name
    area_ha: float = None  # Hectares
    polygon_wkt: str = None  # WKT polygon
    soil_type: str = None  # Soil series

REQUIRED = ["field_id", "name", "area_ha", "polygon_wkt"]

def validate(rec: dict) -> list:
    errors = []
    for f in REQUIRED:
        if f not in rec or rec[f] is None:
            errors.append(f'missing: {f}')
    return errors

sample = {'field_id': 'F-NORTH-04', 'name': 'North 04', 'area_ha': 12.5, 'polygon_wkt': 'POLYGON((...))', 'soil_type': 'Clarion loam'}
print('validation errors:', validate(sample))
print('record ok:', not validate(sample))
